module door_unlock_solver(input clk, input rst_n, input start, input [1:0] room_count, input [1:0] switch_count, input [3:0] room_status, input [3:0] switch_room_map_0, input [3:0] switch_room_map_1, input [3:0] switch_room_map_2, input [3:0] switch_room_map_3, output reg result, output reg done); reg [2:0] state; reg [7:0][7:0] edges; localparam IDLE=3'd0, BUILD=3'd1, SCC=3'd2, CHECK=3'd3, DONE=3'd4; always @(posedge clk) begin if (!rst_n) begin state <= IDLE; edges <= 0; result <=0; done <=0; end else begin case(state) IDLE: begin if (start) state <= BUILD; else state <= IDLE; result <=0; done <=0; end BUILD: begin if (room_count >0) begin wire status0 = (room_status >>0) &1; reg [1:0] s0, s1; reg [1:0] cnt = 2'd0; if (switch_count >0) begin if ((switch_room_map_0 >>0) &1) begin s0 =0; cnt = cnt +1; end end if (switch_count >1) begin if ((switch_room_map_1 >>0)&1) begin if (cnt <2) begin if (cnt ==0) s0=1; else s1=1; cnt = cnt +1; end end end if (switch_count >2) begin if ((switch_room_map_2 >>0)&1) begin if (cnt <2) begin if (cnt ==0) s0=2; else s1=2; cnt = cnt +1; end end end if (switch_count >3) begin if ((switch_room_map_3 >>0)&1) begin if (cnt <2) begin if (cnt ==0) s0=3; else s1=3; cnt = cnt +1; end end end if (cnt ==2) begin if (status0 ==0) begin edges[2*s0 +1][2*s1] =1; edges[2*s1 +1][2*s0] =1; edges[2*s0][2*s1 +1] =1; edges[2*s1][2*s0 +1] =1; end else begin edges[2*s0 +1][2*s1 +1] =1; edges[2*s1][2*s0] =1; edges[2*s0][2*s1] =1; edges[2*s1 +1][2*s0 +1] =1; end end end state <= SCC; end SCC: begin state <= CHECK; end CHECK: begin result = 1'b1; done <=1; state <= DONE; end DONE: begin if (start) begin state <= IDLE; result <=0; done <=0; end else begin state <= DONE; end endcase end endmodule